// No target.checked assignment needed — the browser already handled it.
// On all filters, we use surgical DOM updates instead of render() to
// avoid detaching DOM elements that Cypress may still reference.
// On 'All' filter: toggle the 'completed' class in place.
// On filtered views: remove the <li> if it no longer matches the filter.
todoList.addEventListener('change', function (e) {
  var target = e.target;
  if (!target.classList.contains('toggle')) return;
  var li = target.closest('li');
  if (!li) return;
  var id = parseInt(li.getAttribute('data-id'), 10);
  var todos = loadTodos();
  var todo = todos.find(function (t) { return t.id === id; });
  if (todo) {
    todo.completed = target.checked;
    saveTodos(todos);
    var filter = getCurrentFilter();
    if (filter === '#/' ||
        (filter === '#/active' && !todo.completed) ||
        (filter === '#/completed' && todo.completed)) {
      li.classList.toggle('completed', todo.completed);
    } else {
      li.remove();
    }
    updateTodoCount(todos);
    updateClearCompleted(todos);
    updateToggleAll(todos);
